import pathlib,json,hashlib
O=pathlib.Path(__file__).parent
R=O.parent.parent

def record_live_packet(number,indices,groups,methods=None,findings=None):
 reg=R/'audit-continuation/source-extensions.json';es=json.loads(reg.read_text())['entries'];path=O/'live-source-coverage.json';j=json.loads(path.read_text()) if path.exists() else {'lens':'04','rows':[]};done={x['index'] for x in j['rows']};rows=[]
