  assert i not in done;x=es[i];b=pathlib.Path(x['object']).read_bytes();assert hashlib.sha256(b).hexdigest()==x['sha256'];m=(methods or {}).get(i,{'method':'Every exact registered material range personally read and analyzed for04 in its stated sourcevariant/context; no imported lens coverage.','status':'PERSONALLY_READ_WITH_FINDINGS'})
