 j['rows']=sorted(j['rows']+rows,key=lambda x:x['index']);remaining=[i for i in range(len(es)) if i not in {x['index'] for x in j['rows']}];j.update(registry_count=len(es),registry_sha256=hashlib.sha256(reg.read_bytes()).hexdigest(),completed=len(j['rows']),remaining=len(remaining),first_unfinished=remaining[0] if remaining else None,status='incomplete WITH_FINDINGS' if remaining else 'current registry source discovery accounted WITH_FINDINGS; no lens clearance');path.write_text(json.dumps(j,indent=2)+'\n');packet={'id':f'SEGOVB-INITIAL04-CONTRACT-{number}','dimension':'shared-live-source-extensions','rows':rows,'groups':groups,'findings':findings or [],'first_unfinished_live_index':j['first_unfinished'],'status':j['status'],'execution':'none'};(O/f'contract-groups-{number}.json').write_text(json.dumps(packet,indent=2)+'\n');c=json.loads((O/'checkpoint.json').read_text());c.update(last_packet=packet['id'],live_registry_count=len(es),live_completed=j['completed'],live_remaining=j['remaining'],first_unfinished=f'live index{j["first_unfinished"]}' if remaining else 'current scope material discovery accounted WITH_FINDINGS, unresolved contracts retained');(O/'checkpoint.json').write_text(json.dumps(c,indent=2)+'\n');print('Live',j['completed'],'/',len(es),'first',j['first_unfinished'])
